css:
@import url("s://fonts.googleapis.com/css2?family=Silkscreen:wght@400;700&display=swap");

.keycaps-container,
.keycaps-container * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.keycaps-container {
  display: flex;
  flex-direction: column;
  gap: 1.2em;
  align-items: center;
  position: relative;
  padding: 1em;
}

.keycap-item {
  position: relative;
  width: 4.5em;
  height: 4.5em;
}

.key-radio {
  display: none;
}

.keycap-label {
  --key-base: #cbd5e1;
  --key-shadow: #94a3b8;
  --key-shadow-dark: #64748b;
  --key-top: #f8fafc;
  --text-color: #0f172a;
  --led-active: #00a2ff;

  position: absolute;
  inset: 0;
  border-radius: 0.9em;
  background: var(--key-base);
  box-shadow:
    0 4.5px 0 var(--key-shadow),
    0 6px 0 var(--key-shadow-dark),
    0 10px 15px rgba(0, 0, 0, 0.4),
    inset 0 -1px 1.5px rgba(0, 0, 0, 0.15);
  cursor: pointer;
  user-select: none;
  transition:
    transform 0.12s cubic-bezier(0.175, 0.885, 0.32, 1.275),
    box-shadow 0.12s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  display: flex;
  justify-content: center;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.key-radio:not(:checked) + .keycap-label:hover {
  transform: translateY(1.5px);
  box-shadow:
    0 3px 0 var(--key-shadow),
    0 4.5px 0 var(--key-shadow-dark),
    0 8px 11px rgba(0, 0, 0, 0.35),
    inset 0 -1px 1.5px rgba(0, 0, 0, 0.15);
}

.key-radio:checked + .keycap-label {
  transform: translateY(6px);
  box-shadow:
    0 0px 0 var(--key-shadow),
    0 0px 0 var(--key-shadow-dark),
    0 3px 6px rgba(0, 0, 0, 0.25),
    inset 0 1.5px 3px rgba(0, 0, 0, 0.1);
}

.keycap-top {
  position: absolute;
  top: 3px;
  left: 4px;
  right: 4px;
  bottom: 7px;
  border-radius: 0.65em;
  background: var(--key-top);
  display: flex;
  justify-content: center;
  align-items: center;
  box-shadow:
    inset 0 2px 4px rgba(0, 0, 0, 0.12),
    inset 0 -2px 2px rgba(255, 255, 255, 0.7);
  transition: all 0.12s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.key-radio:checked + .keycap-label .keycap-top {
  top: 4px;
  bottom: 4px;
  box-shadow:
    inset 0 3px 5px rgba(0, 0, 0, 0.2),
    inset 0 -1px 1px rgba(255, 255, 255, 0.2);
}

.led-light {
  position: absolute;
  top: 0.45em;
  right: 0.45em;
  width: 0.38em;
  height: 0.38em;
  border-radius: 50%;
  background-color: rgba(0, 0, 0, 0.22);
  box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.4);
  transition:
    background-color 0.15s ease,
    box-shadow 0.15s ease;
}

.key-radio:checked + .keycap-label .led-light {
  background-color: var(--led-active);
  box-shadow:
    0 0 5px var(--led-active),
    0 0 10px var(--led-active);
}

.keycap-char {
  font-family: "Silkscreen", monospace;
  font-size: 1.05em;
  font-weight: 700;
  color: var(--text-color);
  letter-spacing: -0.5px;
  transition: all 0.12s ease;
  text-shadow: 0 1px 1px rgba(255, 255, 255, 0.8);
}

.key-radio:checked + .keycap-label .keycap-char {
  transform: translateY(0.5px);
  text-shadow: none;
}

.key-white {
  --key-base: #cbd5e1;
  --key-shadow: #94a3b8;
  --key-shadow-dark: #64748b;
  --key-top: #f8fafc;
  --text-color: #0f172a;
  --led-active: #00a2ff;
}

.key-blue {
  --key-base: #2563eb;
  --key-shadow: #1d4ed8;
  --key-shadow-dark: #1e3a8a;
  --key-top: #3b82f6;
  --text-color: #ffffff;
  --led-active: #ffffff;
}

.key-orange {
  --key-base: #c2410c;
  --key-shadow: #7c2d12;
  --key-shadow-dark: #451a03;
  --key-top: #f97316;
  --text-color: #ffffff;
  --led-active: #ffffff;
}

.key-green {
  --key-base: #84cc16;
  --key-shadow: #65a30d;
  --key-shadow-dark: #3f6212;
  --key-top: #a3e635;
  --text-color: #1a2e05;
  --led-active: #ffffff;
}

.key-blue .keycap-char,
.key-orange .keycap-char {
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.4);
}

.key-radio:checked + .key-blue {
  box-shadow:
    0 0px 0 var(--key-shadow),
    0 0px 0 var(--key-shadow-dark),
    0 3px 6px rgba(0, 0, 0, 0.25),
    0 0 20px rgba(59, 130, 246, 0.5),
    inset 0 1.5px 3px rgba(0, 0, 0, 0.1);
  animation: bluePulseLed 2s infinite ease-in-out alternate;
}

.key-radio:checked + .key-orange {
  box-shadow:
    0 0px 0 var(--key-shadow),
    0 0px 0 var(--key-shadow-dark),
    0 3px 6px rgba(0, 0, 0, 0.25),
    0 0 20px rgba(249, 115, 22, 0.5),
    inset 0 1.5px 3px rgba(0, 0, 0, 0.1);
  animation: orangePulseLed 2s infinite ease-in-out alternate;
}

.key-radio:checked + .key-green {
  box-shadow:
    0 0px 0 var(--key-shadow),
    0 0px 0 var(--key-shadow-dark),
    0 3px 6px rgba(0, 0, 0, 0.25),
    0 0 20px rgba(163, 230, 53, 0.5),
    inset 0 1.5px 3px rgba(0, 0, 0, 0.1);
  animation: greenPulseLed 2s infinite ease-in-out alternate;
}

@keyframes bluePulseLed {
  0% {
    box-shadow: 0 0 10px rgba(59, 130, 246, 0.35);
  }
  100% {
    box-shadow: 0 0 24px rgba(59, 130, 246, 0.7);
  }
}

@keyframes orangePulseLed {
  0% {
    box-shadow: 0 0 10px rgba(249, 115, 22, 0.35);
  }
  100% {
    box-shadow: 0 0 24px rgba(249, 115, 22, 0.7);
  }
}

@keyframes greenPulseLed {
  0% {
    box-shadow: 0 0 10px rgba(163, 230, 53, 0.35);
  }
  100% {
    box-shadow: 0 0 24px rgba(163, 230, 53, 0.7);
  }
}

.key-blue .keycap-top {
  background: linear-gradient(180deg, #3b82f6 0%, #2563eb 100%);
}

.key-orange .keycap-top {
  background: linear-gradient(180deg, #f97316 0%, #ea580c 100%);
}

.key-green .keycap-top {
  background: linear-gradient(180deg, #a3e635 0%, #84cc16 100%);
}
